The three tools A, B, C share a single metrics cache that is stale with probability 0.22, and staleness persists for the whole incident. Tool V is independent and never stale. When not stale, each tool reports the true state with probability 0.92 (and 0.04 for each wrong state). A stale tool reports "healthy" with probability 0.97 and each other state with 0.015.

<model>
{
  "sources": [
    {
      "tools": ["A", "B", "C"],
      "fault_prob": 0.22,
      "fault_persists": true
    }
  ],
  "accuracy": {
    "A": 0.92,
    "B": 0.92,
    "C": 0.92,
    "V": 0.8
  },
  "stale_report": {
    "healthy": 0.97,
    "degraded": 0.015,
    "down": 0.015
  }
}
</model>
